using System.Net.Http;using System.Text.RegularExpressions;using System.Security.Cryptography;namespace ISOTool;public sealed class WebLearningEngine{readonly HttpClient c=new();public async Task<List<(string Url,string Text)>> CrawlAsync(Uri s,int max=10){var q=new Queue<Uri>();q.Enqueue(s);var o=new List<(string,string)>();var seen=new HashSet<string>();while(q.Count>0&&o.Count<max){var u=q.Dequeue();if(!seen.Add(u.AbsoluteUri)||!await Allowed(u))continue;try{var b=await c.GetStringAsync(u);var t=Regex.Replace(Regex.Replace(b,"(?is)<script.*?</script>|<style.*?</style>"," "),"<[^>]+>"," ");o.Add((u.AbsoluteUri,Regex.Replace(t,"\\s+"," ").Trim()));}catch{}}return o;}async Task<bool>Allowed(Uri u){try{var x=await c.GetStringAsync(new Uri(u,$"/robots.txt"));return !x.Contains("Disallow: /",StringComparison.OrdinalIgnoreCase);}catch{return false;}}public static double RnnScore(IEnumerable<double>a){double h=0,w=0;foreach(var x in a){h=Math.Tanh(x*.1+h*.05);w+=h*.01;}return 1/(1+Math.Exp(-w));}public static object LlmAdapter(string endpoint,string prompt)=>new{endpoint,prompt,authorizationRequired=true};}
